/* Kept in the measured score region, never floated over the ball or controls. */
#overtimeStatus{margin:6px 0 0;padding:5px 7px;border:1px solid #71998f;border-radius:5px;font:700 13px/1.35 system-ui;color:#f5ecd0;background:#173b40;white-space:normal;overflow-wrap:anywhere}
#overtimeStatus[data-phase="frenzy"]{background:#314768;color:#e5fbff;border-color:#72d7e5}
#overtimeStatus[data-phase="claim"]{background:#574523;color:#fff2b9;border-color:#e9c758}
#shadowIncome{display:block;color:#a7eff5;font-size:12px;min-height:16px}
@media(orientation:landscape) and (max-height:500px){#overtimeStatus{font-size:11px;line-height:1.2;margin-top:3px;padding:3px 5px}#shadowIncome{font-size:10px;min-height:12px}}
body.playing .scorecard #overtimeStatus,body.playing .scorecard #shadowIncome{grid-column:1/-1;letter-spacing:0}
body.playing .scorecard #overtimeStatus{flex:1 0 100%;width:100%;min-width:0}
body.playing .scorecard #shadowIncome{flex:1 0 100%;width:100%;min-width:0}

/* Four compact word indicators replace the old three-region row, not a new HUD layer. */
body.playing #lampHud>div:first-child{display:flex;gap:6px;justify-content:space-between}
body.playing #lampHud>div:first-child span{white-space:nowrap;font-weight:900;font-size:15px}
@media(orientation:portrait){body.playing #lampHud>div:first-child{gap:3px}body.playing #lampHud>div:first-child span{font-size:13px}}

/* Persistent progress is readable even when a world pad is naturally behind equipment. */
body.playing #lampHud>div:first-child span{display:inline-block;min-width:2.9em;text-align:center;padding:3px 4px;border:1px solid #aac3b9;border-radius:5px;background:#193b40;color:#e5eee4}
body.playing #lampHud>div:first-child span.lit{background:#ffe08a;color:#173b40;border-color:#ffe8a9;box-shadow:inset 0 0 0 1px #ad7b24}
@media(orientation:landscape) and (max-height:500px){body.playing #lampHud>div:first-child span{font-size:12px;padding:2px;min-width:2.7em}}

/* Short, narrow landscape: never stack the full HUD down into a flipper. */
@media(orientation:landscape) and (max-width:900px) and (max-height:500px){
 body.pf-game.playing #playStatus{left:calc(var(--safe-left) + 12px);right:calc(var(--safe-right) + 12px);top:calc(var(--pf-header-height) + 8px);width:auto;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:start;gap:8px}
 body.pf-game.playing .scorecard,body.pf-game.playing #lampHud{width:auto;min-width:0;box-sizing:border-box}
 body.pf-game.playing .scorecard{grid-column:1}
 body.pf-game.playing #lampHud{grid-column:3;padding:5px 6px}
 body.pf-game.playing #lampHud>div:first-child{gap:4px}
 body.pf-game.playing #lampHud>div:first-child span{flex:1;min-width:0}
 body.pf-game.playing #playDetails{top:auto;bottom:calc(var(--safe-bottom) + 84px);left:50%;right:auto;transform:translateX(-50%);width:calc((100% - 56px) / 3);max-width:none;gap:3px}
 body.pf-game.playing #playMessages{gap:2px}
 body.pf-game.playing #joke{padding:2px 5px}
}

/* Passive offer on phones; desktop shares one lower-left interaction area. */
body.pf-game.playing #interactionOffer{position:fixed;z-index:35;left:50%;bottom:calc(var(--safe-bottom,0px) + 82px);transform:translateX(-50%);box-sizing:border-box;width:280px;max-width:calc(100vw - 32px);padding:7px 10px;border:1px solid #fff0a8;border-radius:9px;background:#173d40f2;color:#fff7d2;box-shadow:0 2px 8px #102b38aa;display:flex;flex-direction:column;gap:4px;pointer-events:none;text-align:center}
body.pf-game.playing #interactionOffer b{font:900 15px/1.2 system-ui}
body.pf-game.playing #interactionOffer small{font:600 12px/1.2 system-ui}
body.pf-game.playing #interactionOffer progress{display:block;width:100%;height:7px;border:0;border-radius:4px;overflow:hidden;background:#496466;accent-color:#ffe08a}
body.pf-game.playing #interactionOffer progress::-webkit-progress-bar{background:#496466}
body.pf-game.playing #interactionOffer progress::-webkit-progress-value{background:#ffe08a}
body.pf-game.playing #interactionOffer progress::-moz-progress-bar{background:#ffe08a}
body.pf-game #interactionOffer[hidden]{display:none!important}
body.pf-game.playing.interaction-offer-active #left,body.pf-game.playing.interaction-offer-active #right{outline:2px solid #ffe08a;outline-offset:-3px;box-shadow:inset 0 0 12px #ffe08a55}
.offer-arrow{position:absolute;top:3px;left:calc(50% - 5px);color:#ffe08a;font:bold 15px/1 system-ui;pointer-events:none}
.offer-arrow[hidden]{display:none!important}
body.pf-game.playing.interaction-offer-active .control-tip{visibility:hidden}
@media(orientation:portrait){body.pf-game.playing.interaction-offer-active:not(.gate-active) #playDetails{bottom:calc(var(--safe-bottom,0px) + 154px)}}
@media(orientation:landscape) and (max-width:900px) and (max-height:500px){
 body.pf-game.playing #interactionOffer{width:calc((100vw - 56px) / 3);max-width:calc((100vw - 56px) / 3);bottom:calc(var(--safe-bottom,0px) + 80px);padding:5px 8px}
 body.pf-game.playing #interactionOffer b{font-size:13px}
 body.pf-game.playing.interaction-offer-active #playDetails{visibility:hidden}
}
@media (min-width:1000px) and (min-height:600px) and (orientation:landscape) and (hover:hover) and (pointer:fine){
/* Reserve real scene space for the 220px left HUD column in desktop viewports only. */
body.pf-game.playing #playFrame{left:calc(var(--safe-left,0px) + 244px);right:var(--safe-right,0px);width:auto}
/* Fixed activity panel must not inherit a transformed containing block. */
body.pf-game.playing #playDetails{transform:none}
body.pf-game.playing #interactionOffer,body.pf-game.playing #activityPanel{position:fixed;left:calc(var(--safe-left,0px) + 12px);right:auto;top:auto;bottom:calc(var(--safe-bottom,0px) + 90px);transform:none;width:220px;max-width:calc(100vw - 24px);box-sizing:border-box;z-index:35;text-align:left;pointer-events:none;background:#173d40f2}
body.pf-game.playing #activityPanel{padding:9px 10px;border-radius:9px;grid-template-columns:30px minmax(0,1fr)}
body.pf-game.playing #activityPanel .activity-track{height:7px!important}
body.pf-game.playing #activityPanel #activityTitle{font-size:14px}
body.pf-game.playing #activityPanel #activityText{font-size:16px}
body.pf-game.playing #activityPanel #activityHint{font-size:11px}

 body.pf-game.playing #controls .interact-cue,body.pf-game.playing #controls .offer-arrow{display:none!important}
}
/* Borrow the existing mobile joke slot briefly, without reserving extra table space. */
body.pf-game.playing.lottery-status-active #joke{display:none}
#lotteryStatus{font:700 14px/1.3 system-ui;color:#fff1b2;text-align:center;padding:2px 0;white-space:nowrap;max-width:100%;pointer-events:none}
body.pf-game.playing.gate-active #lotteryStatus,body.pf-game.playing.offer-active #lotteryStatus,body.pf-game.playing.activity-active #lotteryStatus,body.pf-game.playing.interaction-offer-active #lotteryStatus{display:none}

/* play-polish hides legacy jokes globally: explicitly restore the phone slot only
   when no high-priority instruction owns it. Never overwrite its event text. */
body.pf-game.playing.lottery-mobile:not(.lottery-status-active):not(.lottery-priority-active):not(.gate-active):not(.offer-active):not(.activity-active):not(.interaction-offer-active):not(.mail-active) #joke{display:block;font:600 14px/1.3 system-ui;color:#fff4d6;background:#173b40;border:1px solid #9aafa4;border-radius:5px;padding:3px 5px;text-align:center;overflow-wrap:anywhere}
body.pf-game.playing.lottery-mobile #lotteryStatus{background:#173b40;color:#fff1b2;border:1px solid #e6cc79;border-radius:5px;padding:3px 5px;box-shadow:0 1px 3px #081d26;box-sizing:border-box}
body.pf-game.playing.lottery-priority-active #lotteryStatus,body.pf-game.playing.lottery-priority-active #joke,body.pf-game.playing.lottery-mobile #playDetails:has(#comic.pop) #joke{display:none}

import {filterReleased,resolveCatalogChannel} from './release.mjs';
const escape = value => String(value).replace(/[&<>"']/g, char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const fastHandsEntries=new Map([
 ['fast-hands',{href:'/games/fast-hands/?intro=1',image:'/assets/fast-hands-card-v2.webp'}],
 ['fast-hands-catch',{href:'/games/fast-hands/catch.html?intro=1',image:'/games/fast-hands/assets/intro-catch-generated.webp'}],
 ['fast-hands-duel',{href:'/games/fast-hands/duel.html?intro=1',image:'/games/fast-hands/assets/intro-duel-generated.webp'}]
]);
const publicDestinations = new Map(['formosabattle','echosboundary','taiwankart','taiwanfighter','taiwanpunchline','arcadeplatform'].map(id=>[id,`https://${id}.playformosa.workers.dev/`]));
publicDestinations.set('soul10power','https://soul10power.vercel.app/');
function validateExternal(entry,needsImage=false) {
  if(!publicDestinations.has(entry.id)||publicDestinations.get(entry.id)!==entry.href)throw new Error('Expected an approved exact external URL');
  if(needsImage && typeof entry.image!=='string')throw new Error('Expected a local portal image');
  for(const image of [entry.image,entry.logo].filter(Boolean))if(!/^\/assets\/portal-[a-z0-9-]+\.(?:png|webp|jpg|svg)$/.test(image))throw new Error('Expected a local portal image');
}
const portalArrow='<svg class="portal-arrow" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M5 15 15 5M5 5h10v10"/></svg>';
const externalLink=(entry,label)=>`<a class="button portal-cta" href="${escape(['taiwanfighter','taiwanpunchline'].includes(entry.id)?`/api/play-counts/entries/${entry.id}`:entry.href)}" target="_blank" rel="noopener noreferrer" aria-label="${escape(label)}：${escape(entry.title)}（另開新分頁）">${escape(label)} ${portalArrow}</a>`;
function renderExternalGame(entry) {
 return `<article class="portal-card portal-card--${escape(entry.id)}" data-external-id="${escape(entry.id)}"><div class="portal-art"><img src="${escape(entry.image)}" alt="" width="1672" height="941" loading="lazy" decoding="async">${entry.logo?`<img class="portal-game-logo" src="${escape(entry.logo)}" alt="" width="1446" height="1120" loading="lazy" decoding="async">`:''}<span class="portal-art-label">${escape(entry.eyebrow)}</span></div><div class="portal-card-body"><p class="portal-genre">${escape(entry.genre)}</p><h3>${escape(entry.title)}</h3><p class="portal-description">${escape(entry.description)}</p>${entry.id==='taiwanpunchline'?'<p class="play-count" title="本功能啟用後，從預覽平台點擊進入拳民的累計次數；不是遊戲內開局次數" data-play-count="taiwanpunchline" aria-live="polite">開玩次數讀取中…</p><small>平台入口累計・非遊戲開局數</small>':entry.id==='taiwanfighter'?'<p class="play-count" title="本功能啟用後，從平台點擊進入武鬥的累計次數；不是遊戲內開局次數" data-play-count="taiwanfighter" aria-live="polite">開玩次數讀取中…</p>':''}<div class="portal-card-bottom"><span class="portal-destination">獨立遊戲網站</span>${externalLink(entry,'前往遊玩')}</div></div></article>`;
}
function renderPlatform(entry) {
 return `<article class="platform-feature" data-external-id="${escape(entry.id)}"><div class="platform-brand"><p class="portal-genre">${escape(entry.brand)} · 小遊戲平台</p><h3>${escape(entry.title)}</h3><span class="platform-brand-line" aria-hidden="true"></span></div><div class="platform-copy"><p>${escape(entry.description)}</p><div class="platform-actions">${externalLink(entry,'前往遊戲平台')}<span class="portal-destination">獨立平台・另開新分頁</span></div></div></article>`;
}
export function renderPage({games,events,minigames=[],externalGames=[],platforms=[]},{channel='production'}={}) {
  resolveCatalogChannel({channel});
  const releasedGames=filterReleased(externalGames,channel),releasedPlatforms=filterReleased(platforms,channel);
  releasedGames.forEach(entry=>validateExternal(entry,true));
  releasedPlatforms.forEach(entry=>validateExternal(entry));
  const externalSections=`${releasedGames.length?`<section class="portal-section" id="big-games" aria-labelledby="big-games-title"><div class="portal-section-heading"><div><p class="eyebrow">INDEPENDENT WORLDS</p><h2 id="big-games-title">大遊戲</h2></div><p class="portal-section-note">${releasedGames.length} 個世界，各自精彩。</p></div><p class="portal-intro">從山海江湖到島嶼街頭，選一個世界，展開你的旅程。</p><p class="portal-external-note">以下遊戲將在新分頁開啟，保留各自的遊戲介面。</p><div class="portal-grid">${releasedGames.map(renderExternalGame).join('')}</div></section>`:''}${releasedPlatforms.length?`<section class="portal-section platform-section" id="platforms" aria-labelledby="platforms-title"><div class="portal-section-heading"><div><p class="eyebrow">MORE WAYS TO PLAY</p><h2 id="platforms-title">還想再玩一款？</h2></div></div>${releasedPlatforms.map(renderPlatform).join('')}</section>`:''}`;
  const available=games.filter(game=>game.status==='available');
  const availableMinigames=minigames.filter(game=>game.status==='available');
  for (const game of [...available,...availableMinigames]) {
    const fastHands=fastHandsEntries.get(game.id);
    if (fastHands) {
      if(game.href!==fastHands.href)throw new Error('Expected the exact Fast Hands entrance');
      if(game.image!==fastHands.image)throw new Error('Expected the matching Fast Hands cover');
    } else {
      if (!/^\/games\/[a-z0-9-]+\/$/.test(game.href)) throw new Error('Expected a local game route');
      if (game.image && !/^\/assets\/[a-z0-9-]+\.(?:svg|png|webp|jpg)$/.test(game.image)) throw new Error('Expected a local card image');
    }
  }
  const nextEvents=events.filter(event=>!available.some(game=>game.event===event));
  const featured=available[0];
  const renderCard=(game,collection)=>`<article class="game-card"><a href="${escape(game.href)}" class="game-thumbnail" tabindex="-1" aria-hidden="true"><img src="${escape(game.image || "/assets/hero-long-jump.png")}"${game.image ? (game.imageStyle==='illustration' ? ' class="game-illustration"' : ' class="game-scene"') : ''} alt="" width="1536" height="1024" loading="lazy"><span>${escape(collection)} · ${escape(game.event)}</span></a><div class="game-info"><p class="game-kicker">${escape(game.kicker || "第一個挑戰，先落地再說。")}</p><h3>${escape(game.title)}</h3><p class="event-label">${escape(game.event)}${game.label ? ` · ${escape(game.label)}` : ""}</p><p class="input-chip"><span aria-hidden="true">⌨ / ☝</span> ${escape(game.input || "鍵盤／觸控")}</p>${['long-jump','hurdles','high-jump','pole-vault','shot-put','discus','sprint-100m','run-400m','run-1500m','javelin','overtime-pinball','reaction-rod','beer-slide','tower-climb','fast-hands','fast-hands-catch','fast-hands-duel','courtesy-contest'].includes(game.id)?`<p class="play-count" title="本功能啟用後累計的開局紀錄" data-play-count="${escape(game.id)}" aria-live="polite">遊玩次數讀取中…</p>`:''}</div><a class="button button-primary game-cta" href="${escape(game.href)}" aria-label="開始挑戰：${escape(game.title)}">開始挑戰 <span aria-hidden="true">↗</span></a></article>`;
  return `<!doctype html>
<html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#fff8e9"><meta name="description" content="島遊無界的小遊戲實驗場。操作不一定專業，跌倒一定精彩。從四肢各有想法開始，挑戰不太正經的十項全能。"><title>島遊無界 PLAYFORMOSA｜小遊戲實驗場</title><link rel="stylesheet" href="/assets/home.css"><link rel="icon" type="image/png" sizes="32x32" href="./assets/app-icons/platform/favicon-32.png"><link rel="icon" type="image/png" sizes="48x48" href="./assets/app-icons/platform/favicon-48.png"><link rel="apple-touch-icon" sizes="180x180" href="./assets/app-icons/platform/apple-touch-icon.png"><link rel="manifest" href="./manifest.webmanifest"><meta name="application-name" content="島遊無界"><meta name="apple-mobile-web-app-title" content="島遊無界"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes"></head>
<body data-catalog-channel="${channel}"${releasedGames.length||releasedPlatforms.length?' class="has-portal"':''}><a class="skip-link" href="#main">跳到主要內容</a>
<div class="page-shell"><header class="site-header"><a class="wordmark" href="/" aria-label="島遊無界 PLAYFORMOSA 首頁"><span>島遊無界</span><small>PLAYFORMOSA</small></a><nav aria-label="主要導覽"><a href="#minigames">小遊戲</a><a href="#decathlon">十項全能</a>${releasedGames.length?'<a href="#big-games">大遊戲</a>':''}${releasedPlatforms.length?'<a href="#platforms">play. one more.</a>':''}<a href="#about">關於</a></nav></header>
<main id="main"><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">小遊戲，大失控。</p><h1 id="hero-title">操作不一定<span class="underline orange">專業</span>，<br>跌倒一定<span class="underline teal">精彩</span>。</h1><p class="hero-subtitle">島遊無界的小遊戲實驗場</p><div class="hero-actions">${featured ? `<a class="button button-primary" href="${escape(featured.href)}">先跳一場 <span aria-hidden="true">↗</span></a>` : ''}<a class="button button-secondary" href="#games">逛逛遊戲 <span aria-hidden="true">↓</span></a></div></div><div class="hero-art"><div class="art-halo" aria-hidden="true"></div><img src="/assets/hero-long-jump.png" alt="一位手腳各自亂飛的逗趣跳遠選手" width="1536" height="1024" fetchpriority="high"><span class="comic-sticker" aria-hidden="true">四肢各有想法！</span><span class="hero-caption">認真起跳，隨緣著陸。</span></div></section>
<section class="series" id="decathlon" aria-labelledby="series-title"><div class="series-heading"><div><p class="eyebrow">THE VERY UNPROFESSIONAL GAMES</p><h2 id="series-title">十項全能挑戰</h2></div><p class="progress">目前開放 <strong>${available.length}<span> / ${events.length}</span></strong> 項</p></div><div class="series-body"><div id="games" class="game-list">${available.map(game=>renderCard(game,'十項全能')).join('')}</div>${nextEvents.length?`<details class="roadmap"><summary>查看後續項目 <span aria-hidden="true">＋</span></summary><div class="roadmap-content"><p>還有 ${nextEvents.length} 個項目正在暖身。先把這一跳玩明白！</p><ul>${nextEvents.map(event=>`<li><span>${escape(event)}</span><small>尚未開放</small></li>`).join('')}</ul><p class="roadmap-note">後續項目為開發規劃，開放時間未定。</p></div></details>`:''}</div></section>
<section class="series minigames" id="minigames" aria-labelledby="minigames-title"><div class="series-heading"><div><p class="eyebrow">SMALL GAMES, BIG REACTIONS</p><h2 id="minigames-title">小遊戲</h2></div><p class="progress">目前開放 <strong>${availableMinigames.length}</strong> 款</p></div><div class="series-body"><div class="game-list">${availableMinigames.map(game=>renderCard(game,'小遊戲')).join('')}${availableMinigames.length ? '' : '<p class="minigames-empty">更多怪點子，慢慢登場。</p>'}</div></div></section>
${externalSections}
<section id="about" class="about" aria-labelledby="about-title"><h2 id="about-title">島遊無界工作室 <span>| PLAYFORMOSA STUDIO</span></h2><p>我們把奇怪的點子，做成真的能玩的遊戲。</p></section></main><footer><span>MADE FOR A LITTLE FUN.</span><span class="home-count" data-home-count title="本功能啟用後累計；同一瀏覽器短時間重訪不重複計入" aria-live="polite">瀏覽次數讀取中…</span><a href="#main">回到上方 ↑</a></footer></div><script type="module" src="/assets/play-counts.mjs"></script></body></html>`;
}

import {withProvenanceSession,manifestText} from './provenance-session.mjs';
// Exact additive boundary for the approved PinballFocusRestart import. Live behavior tests
// continue reading node:fs and runtime modules, never this historical view.
import {readFileSync as actual} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {resolve,relative,sep,isAbsolute} from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
export const sha256=b=>createHash('sha256').update(b).digest('hex');
export const gitBlob=b=>createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
const baselineBytes=actual(new URL('../../docs/pinball-focus-restart/BASELINE.json',import.meta.url));
assert.equal(sha256(baselineBytes),'c54eb191620ca6b5ea165ba385ca5c87ede6560117099a2d843457825ba0fb87','immutable PinballFocusRestart parent and admitted paths');
const freeze=value=>{if(value&&typeof value==='object'){Object.values(value).forEach(freeze);Object.freeze(value);}return value;};
export const baseline=freeze(JSON.parse(baselineBytes));
const previous=new Map(baseline.files.map(f=>[f.path,f.gitBlob]));
export function verifyBase(b){
 assert.equal(b.baseCommit,'c8afb9c3aff49ab08ec842b297524b3aa46edc32');assert.equal(b.baseTree,'6fa4a636c4c0e081785e51b4b216bcfe308cb093');assert.deepEqual(b,baseline);
 const tree={};for(const f of b.files){const parts=f.path.split('/');let d=tree;for(const name of parts.slice(0,-1))d=d[name]??={};assert.ok(!d[parts.at(-1)],'duplicate parent path');d[parts.at(-1)]={file:f};}
 function digest(d){const entries=Object.entries(d).sort(([a,x],[b,y])=>Buffer.compare(Buffer.from(a+(x.file?'':'/')),Buffer.from(b+(y.file?'':'/'))));const bytes=Buffer.concat(entries.map(([n,x])=>Buffer.concat([Buffer.from(`${x.file?x.file.mode:'40000'} ${n}\0`),Buffer.from(x.file?x.file.gitBlob:digest(x),'hex')])));return createHash('sha1').update(`tree ${bytes.length}\0`).update(bytes).digest('hex');}
 assert.equal(digest(tree),b.baseTree);return true;
}
verifyBase(baseline);
const manifestPath='docs/pinball-focus-restart/MANIFEST.json';
let cachedText,cached;const validated=new WeakSet();
function uncached_manifest(){const url=new URL('../../'+manifestPath,import.meta.url),text=manifestText(url,()=>actual(url,'utf8'));if(text!==cachedText){const parsed=freeze(JSON.parse(text));cachedText=text;cached=parsed;}return cached;}

export function validate(m){
 if(m===cached&&validated.has(m))return m;
 assert.equal(m.baseCommit,baseline.baseCommit);assert.equal(m.baseTree,baseline.baseTree);
 assert.deepEqual(m.files.map(f=>f.path).sort(),baseline.modifiedPaths);
